;(function(){
  /* first-launch model download banner (inline styles, independent of cached CSS) */
  var el=null,stop=false,timer=null;
  function css(n,o){for(var k in o)n.style[k]=o[k]}
  function show(s){
    if(!el){el=document.createElement('div');el.setAttribute('role','status');document.body.insertBefore(el,document.body.firstChild)}
    var err=s.state==='ERROR',dl=s.state==='DOWNLOADING';
    el.textContent='';
    css(el,{position:'fixed',top:'0',left:'0',right:'0',zIndex:'2147483000',padding:'12px 18px',fontSize:'14px',fontFamily:'system-ui,Segoe UI,sans-serif',
      background:err?'#3a1519':'#12263a',color:err?'#ffd3d3':'#cfe6ff',borderBottom:'2px solid '+(err?'#a33':'#2b5d8a'),boxShadow:'0 4px 18px rgba(0,0,0,.5)'});
    var b=document.createElement('strong');b.textContent=(err?'AI model setup problem':dl?'Setting up (first launch only)':'Getting the AI ready')+'  ';
    var m=document.createElement('span');m.textContent=s.message||'';
    el.appendChild(b);el.appendChild(m);
    if(dl&&s.total>0){
      var bar=document.createElement('div');css(bar,{height:'8px',borderRadius:'4px',background:'rgba(255,255,255,.18)',overflow:'hidden',marginTop:'8px'});
      var i=document.createElement('div');css(i,{height:'100%',width:s.percent+'%',background:'#4aa3ff',transition:'width .6s'});
      bar.appendChild(i);el.appendChild(bar);
      var p=document.createElement('div');css(p,{marginTop:'4px',fontSize:'12px',opacity:'.8'});p.textContent=s.percent+'% - the risk model works already; the assistant chat unlocks when the download finishes.';el.appendChild(p)
    }
    document.body.style.paddingTop=el.offsetHeight+'px'
  }
  function hide(){if(el){el.remove();el=null;document.body.style.paddingTop=''}}
  function poll(){
    if(stop)return;
    fetch('/setup/status',{cache:'no-store'}).then(function(r){return r.ok?r.json():null}).then(function(j){
      if(j){ if(j.state==='READY'){hide();stop=true;return} show(j) }
      timer=setTimeout(poll,1500)
    }).catch(function(){timer=setTimeout(poll,1500)})
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',poll);else poll()
})();
